import * as React from "react"
import { addPropertyControls, ControlType, useIsStaticRenderer } from "framer"
// @ts-ignore Existing Framer design component has no TypeScript declaration
import BotanikaButton from "https://framer.com/m/Primary-Button-2-DI39FD.js@W1LpBGdtIyikD95UJS2a"

interface Field { placeholder?: string; value?: string }
interface Props {
    formId?: string
    withName?: boolean
    nameField?: Field
    withEmail?: boolean
    email?: Field
    withPhone?: boolean
    phoneInput?: React.ReactNode
    withMessage?: boolean
    message?: Field
    submitButton?: React.ReactNode
    layout?: "horizontal" | "vertical"
    inputs?: { fill?: string; color?: string; placeholderColor?: string; error?: string }
    button?: { label?: string; fill?: string; color?: string; fontWeight?: number }
    fontFamily?: string
    fontWeight?: number
    fontSize?: number
    gap?: number
    padding?: number
    borderRadius?: number
    style?: React.CSSProperties
    onSubmit?: () => void
}

/**
 * @framerIntrinsicWidth 800
 * @framerIntrinsicHeight 360
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function FormSpark({
    formId = "", withName = true, nameField = { placeholder: "Name" },
    withEmail = true, email = { placeholder: "Email" },
    withPhone = true, phoneInput, withMessage = true, message = { placeholder: "Message" },
    submitButton, layout = "horizontal", inputs = {}, button = {},
    fontFamily = "Inter", fontWeight = 400, fontSize = 16, gap = 15, padding = 15, borderRadius = 8,
    style, onSubmit,
}: Props) {
    const staticRenderer = useIsStaticRenderer()
    const uid = React.useId().replace(/:/g, "")
    const formRef = React.useRef<HTMLFormElement>(null)
    const [language, setLanguage] = React.useState<"en" | "vi">("en")
    React.useEffect(() => {
        const host = window as Window & { __botanikaInlineLanguage?: "en" | "vi" }
        const sync = () => setLanguage(host.__botanikaInlineLanguage ?? "en")
        sync()
        window.addEventListener("botanika:inline-language", sync)
        return () => window.removeEventListener("botanika:inline-language", sync)
    }, [])
    const vi = language === "vi"
    React.useEffect(() => {
        for (const element of Array.from(formRef.current?.elements ?? [])) {
            const field = element as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
            if (typeof field.setCustomValidity === "function") field.setCustomValidity("")
        }
    }, [language])
    const localizeValidation = (event: React.FormEvent<HTMLFormElement>) => {
        const field = event.target as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
        if (typeof field.setCustomValidity !== "function") return
        field.setCustomValidity("")
        if (field.validity.valid) return
        let message = vi ? "Vui lòng kiểm tra thông tin" : "Please check this value"
        if (field.validity.valueMissing) message = vi ? "Vui lòng nhập thông tin" : "Please complete this field"
        else if (field.validity.typeMismatch && field instanceof HTMLInputElement && field.type === "email") message = vi ? "Vui lòng nhập email hợp lệ" : "Please enter a valid email"
        else if (field.validity.tooShort && "minLength" in field) message = vi ? `Nhập ít nhất ${field.minLength} ký tự` : `Enter at least ${field.minLength} characters`
        field.setCustomValidity(message)
    }
    const clearValidation = (event: React.FormEvent<HTMLFormElement>) => {
        const field = event.target as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
        if (typeof field.setCustomValidity === "function") field.setCustomValidity("")
    }
    const translate = (value: string) => {
        const pairs: Record<string, string> = { "Name": "Tên", "Email": "Email", "Message": "Tin nhắn", "Contact Us": "Liên hệ", "Contact us": "Liên hệ", "Send": "Gửi" }
        return vi ? (pairs[value] ?? value) : (Object.entries(pairs).find(([, text]) => text === value)?.[0] ?? value)
    }
    const [status, setStatus] = React.useState<"idle" | "sending" | "success" | "error">("idle")
    const [error, setError] = React.useState("")
    const fill = inputs.fill ?? "rgb(24,24,27)"
    const color = inputs.color ?? "#FFFFFF"
    const label = translate(button.label ?? "Contact Us")
    const inputStyle: React.CSSProperties = {
        width: "100%", minWidth: 0, boxSizing: "border-box", border: "1px solid transparent", borderRadius,
        padding, background: fill, color, colorScheme: "dark", font: "inherit", lineHeight: 1.4, outlineOffset: 3,
    }
    const phone = React.Children.count(phoneInput) ? phoneInput : <CountryPhoneInput language={language} inputStyle={inputStyle} placeholderColor={inputs.placeholderColor ?? "#80858F"} fill={fill} color={color} radius={borderRadius} />
    const visual = React.Children.count(submitButton) ? submitButton : <BotanikaButton variant="iNJPywoA_" xf1v73sao={label} OUtKeGusD={undefined} Y5bHOjiAw="13px 70px 14px 24px" style={{ height: 44 }} />

    async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault()
        if (staticRenderer || status === "sending") return
        const form = event.currentTarget
        if (!form.reportValidity()) return
        if (!formId.trim()) { setError("missing"); setStatus("error"); return }
        setError(""); setStatus("sending")
        try {
            const response = await fetch(`https://api.formspark.io/${encodeURIComponent(formId.trim())}`, {
                method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" },
                body: JSON.stringify(Object.fromEntries(new FormData(form).entries())),
            })
            if (!response.ok) throw new Error("Submission failed")
            setStatus("success"); onSubmit?.()
        } catch { setStatus("error"); setError("failed") }
    }

    return <div className={`botanika-form-${uid}`} lang={language} style={{ ...style, width: "100%", height: "100%", minWidth: 0, fontFamily, fontWeight, fontSize, color }}>
        <style>{`.botanika-form-${uid} input:is(:-webkit-autofill,:autofill){-webkit-box-shadow:0 0 0 1000px ${fill} inset!important;box-shadow:0 0 0 1000px ${fill} inset!important;-webkit-text-fill-color:${color}!important;color:${color}!important;caret-color:${color};background-color:${fill}!important}.botanika-form-${uid} input::placeholder,.botanika-form-${uid} textarea::placeholder{color:${inputs.placeholderColor ?? "#80858F"}}.botanika-form-${uid} .contact-fields{display:grid;grid-template-columns:${layout === "horizontal" ? "repeat(2,minmax(0,1fr))" : "minmax(0,1fr)"};gap:${gap}px}@media(max-width:520px){.botanika-form-${uid} .contact-fields{grid-template-columns:minmax(0,1fr)}}`}</style>
        {status === "success" ? <div role="status" style={{ minHeight: 120, display: "grid", placeItems: "center", color }}>{vi ? "✓ Đã gửi" : "✓ Message sent"}</div> : <form ref={formRef} lang={language} onInvalidCapture={localizeValidation} onInputCapture={clearValidation} onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap, width: "100%", height: "100%", minWidth: 0 }}>
            {(withName || withEmail) && <div className="contact-fields" style={{ gridTemplateColumns: !withName || !withEmail ? "minmax(0,1fr)" : undefined }}>
                {withName && <input type="text" name="name" autoComplete="name" aria-label={translate(nameField.placeholder || "Name")} placeholder={translate(nameField.placeholder || "Name")} defaultValue={nameField.value || ""} required style={inputStyle} />}
                {withEmail && <input type="email" name="email" autoComplete="email" aria-label={translate(email.placeholder || "Email")} placeholder={translate(email.placeholder || "Email")} defaultValue={email.value || ""} required style={inputStyle} />}
            </div>}
            {withPhone && <div style={{ width: "100%", minWidth: 0, position: "relative", zIndex: 2 }}>{phone}</div>}
            {withMessage && <textarea name="message" aria-label={translate(message.placeholder || "Message")} placeholder={translate(message.placeholder || "Message")} defaultValue={message.value || ""} required style={{ ...inputStyle, flex: 1, minHeight: 100, resize: "vertical" }} />}
            <div style={{ alignSelf: "flex-start" }}>
                <button type="submit" aria-label={label} disabled={status === "sending"} style={{ display: "block", position: "relative", padding: 0, border: 0, background: "transparent", font: "inherit", cursor: status === "sending" ? "wait" : "pointer", opacity: status === "sending" ? .6 : 1 }}>
                    <div aria-hidden="true" {...({ inert: "" } as any)} style={{ pointerEvents: "none" }}>{visual}</div>
                </button>
            </div>
            {status === "sending" && <span role="status" style={{ fontSize: 13 }}>{vi ? "Đang gửi…" : "Sending…"}</span>}
            {error && <span role="alert" style={{ color: inputs.error ?? "#EE4444", fontSize: 13 }}>{error === "missing" ? (vi ? "Chưa thể gửi, vui lòng thử lại sau" : "Unable to send, please try again later") : (vi ? "Gửi chưa thành công, vui lòng thử lại" : "Could not send your message, please try again")}</span>}
        </form>}
    </div>
}


function CountryPhoneInput({ language, inputStyle, placeholderColor, fill, color, radius }: {
    language: "en" | "vi"; inputStyle: React.CSSProperties; placeholderColor: string; fill: string; color: string; radius: number
}) {
    const vi = language === "vi"
    const root = React.useRef<HTMLDivElement>(null)
    const trigger = React.useRef<HTMLButtonElement>(null)
    const search = React.useRef<HTMLInputElement>(null)
    const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([])
    const listId = React.useId()
    const [open, setOpen] = React.useState(false)
    const [query, setQuery] = React.useState("")
    const [code, setCode] = React.useState("US")
    const [number, setNumber] = React.useState("")
    const [active, setActive] = React.useState(0)
    const countries = React.useMemo(() => {
        let names: Intl.DisplayNames | undefined
        try { names = new Intl.DisplayNames([language], { type: "region" }) } catch {}
        return phoneDefaults.countries.map(country => ({ ...country, title: names?.of(country.code) ?? country.name }))
            .sort((a, b) => a.title.localeCompare(b.title, language))
    }, [language])
    const normalized = (text: string) => text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").toLowerCase()
    const filtered = React.useMemo(() => countries.filter(country => normalized(`${country.title} ${country.name} ${country.code} ${country.dial}`).includes(normalized(query.trim()))), [countries, query])
    const selected = countries.find(country => country.code === code) ?? countries[0]
    React.useEffect(() => {
        if (!open) return
        search.current?.focus()
        const outside = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false) }
        window.addEventListener("pointerdown", outside)
        return () => window.removeEventListener("pointerdown", outside)
    }, [open])
    const choose = (country: typeof selected) => { setCode(country.code); setOpen(false); setQuery(""); trigger.current?.focus() }
    const move = (next: number) => { const index = Math.max(0, Math.min(filtered.length - 1, next)); setActive(index); optionRefs.current[index]?.focus(); optionRefs.current[index]?.scrollIntoView({ block: "nearest" }) }
    return <div ref={root} style={{ position: "relative", width: "100%", minWidth: 0 }}>
        <input type="hidden" name="phone" value={number.trim() ? `${selected.dial} ${number.trim()}` : ""} />
        <div style={{ display: "flex", minWidth: 0, background: fill, borderRadius: radius }}>
            <button ref={trigger} type="button" aria-label={`${vi ? "Chọn quốc gia" : "Choose country"}: ${selected.title}`} aria-haspopup="listbox" aria-expanded={open} aria-controls={open ? listId : undefined}
                onClick={() => { setOpen(value => !value); setQuery(""); setActive(0) }}
                onKeyDown={event => { if (event.key === "ArrowDown") { event.preventDefault(); setOpen(true) } }}
                style={{ ...inputStyle, width: "auto", display: "flex", alignItems: "center", gap: 7, flexShrink: 0, borderTopRightRadius: 0, borderBottomRightRadius: 0, cursor: "pointer" }}>
                <span aria-hidden="true">{selected.flag}</span><span>{selected.dial}</span><span aria-hidden="true" style={{ color: placeholderColor, fontSize: 10 }}>▾</span>
            </button>
            <input type="tel" autoComplete="tel-national" inputMode="tel" aria-label={vi ? "Điện thoại" : "Phone number"} placeholder={vi ? "Điện thoại" : "Phone number"}
                value={number} onChange={event => setNumber(event.target.value)} style={{ ...inputStyle, flex: 1, width: 0, borderTopLeftRadius: 0, borderBottomLeftRadius: 0 }} />
        </div>
        {open && <div data-lenis-prevent="true" onWheel={event => event.stopPropagation()} onTouchMove={event => event.stopPropagation()}
            onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); setOpen(false); trigger.current?.focus() } }}
            style={{ position: "absolute", top: "calc(100% + 8px)", left: 0, width: "100%", zIndex: 20, background: fill, color, border: "1px solid #343438", borderRadius: radius, boxShadow: "0 12px 32px #0008", overflow: "hidden" }}>
            <div style={{ padding: 8, borderBottom: "1px solid #343438" }}>
                <input ref={search} type="search" aria-label={vi ? "Tìm quốc gia" : "Search countries"} placeholder={vi ? "Tìm quốc gia / mã vùng" : "Search countries or dial code"}
                    value={query} onChange={event => { setQuery(event.target.value); setActive(0) }}
                    onKeyDown={event => { if (event.key === "ArrowDown") { event.preventDefault(); move(0) } if (event.key === "Enter") { event.preventDefault(); if (filtered[active]) choose(filtered[active]) } }}
                    style={{ ...inputStyle, padding: 8 }} />
            </div>
            <div id={listId} role="listbox" aria-label={vi ? "Quốc gia" : "Countries"} data-lenis-prevent="true"
                style={{ maxHeight: 200, minHeight: 0, overflowY: "auto", overflowX: "hidden", overscrollBehavior: "contain", touchAction: "pan-y", padding: 4, scrollbarWidth: "thin" }}
                onKeyDown={event => {
                    if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) { event.preventDefault(); move(event.key === "Home" ? 0 : event.key === "End" ? filtered.length - 1 : active + (event.key === "ArrowDown" ? 1 : -1)) }
                    if (event.key === "Tab") setOpen(false)
                }}>
                {filtered.length ? filtered.map((country, index) => <button key={country.code} ref={element => { optionRefs.current[index] = element }} type="button" role="option" aria-selected={country.code === code}
                    onFocus={() => setActive(index)} onClick={() => choose(country)}
                    style={{ display: "flex", alignItems: "center", gap: 10, width: "100%", padding: "10px 8px", border: 0, borderRadius: 5, background: country.code === code ? "rgba(255,255,255,.08)" : "transparent", color, font: "inherit", textAlign: "left", cursor: "pointer" }}>
                    <span aria-hidden="true">{country.flag}</span><span style={{ flex: 1 }}>{country.title}</span><span style={{ color: placeholderColor }}>{country.dial}</span>
                </button>) : <div role="status" style={{ padding: 12, color: placeholderColor }}>{vi ? "Không có kết quả" : "No countries found"}</div>}
            </div>
        </div>}
    </div>
}

const fieldControls = (placeholder: string) => ({
    placeholder: { type: ControlType.String as const, title: "Placeholder", defaultValue: placeholder },
    value: { type: ControlType.String as const, title: "Value", defaultValue: "" },
})
addPropertyControls(FormSpark, {
    formId: { type: ControlType.String, title: "ID", description: "Your FormSpark form ID" },
    withName: { type: ControlType.Boolean, title: "Name", defaultValue: true },
    nameField: { type: ControlType.Object, title: " ", controls: fieldControls("Name"), hidden: p => !p.withName },
    withEmail: { type: ControlType.Boolean, title: "Email", defaultValue: true },
    email: { type: ControlType.Object, title: " ", controls: fieldControls("Email"), hidden: p => !p.withEmail },
    withPhone: { type: ControlType.Boolean, title: "Phone", defaultValue: true },
    phoneInput: { type: ControlType.Slot, title: "Phone Input", maxCount: 1 },
    withMessage: { type: ControlType.Boolean, title: "Message", defaultValue: true },
    message: { type: ControlType.Object, title: " ", controls: fieldControls("Message"), hidden: p => !p.withMessage },
    layout: { type: ControlType.Enum, title: "Layout", options: ["horizontal", "vertical"], defaultValue: "horizontal" },
    inputs: { type: ControlType.Object, title: "Inputs", controls: {
        fill: { type: ControlType.Color, title: "Fill", defaultValue: "#18181B" },
        color: { type: ControlType.Color, title: "Text", defaultValue: "#FFFFFF" },
        placeholderColor: { type: ControlType.Color, title: "Placeholder", defaultValue: "#80858F" },
        error: { type: ControlType.Color, title: "Error", defaultValue: "#EE4444" },
    } },
    submitButton: { type: ControlType.Slot, title: "Your Button", maxCount: 1 },
    button: { type: ControlType.Object, title: "Button", controls: {
        label: { type: ControlType.String, title: "Label", defaultValue: "Contact Us" },
    } },
    fontFamily: { type: ControlType.String, title: "Family", defaultValue: "Inter" },
    fontWeight: { type: ControlType.Number, title: "Weight", defaultValue: 400, min: 100, max: 900, step: 100 },
    fontSize: { type: ControlType.Number, title: "Font Size", defaultValue: 16, min: 10, max: 32 },
    padding: { type: ControlType.Number, title: "Padding", defaultValue: 15, min: 0, max: 40 },
    borderRadius: { type: ControlType.Number, title: "Radius", defaultValue: 8, min: 0, max: 40 },
    gap: { type: ControlType.Number, title: "Gap", defaultValue: 15, min: 0, max: 40 },
    onSubmit: { type: ControlType.EventHandler },
})

